export interface FramePublisherOptions<T> {
  request: (callback: () => void) => number;
  cancel: (handle: number) => void;
  publish: (value: T) => void;
}

export interface FramePublisher<T> {
  schedule: (value: T) => void;
  immediate: (value: T) => void;
  cancel: () => void;
  activate: () => void;
  dispose: () => void;
}

/** Coalesce presentation only. Canonical edits and callbacks belong to callers
 * and must run synchronously before scheduling their latest visual snapshot.
 */
export function createFramePublisher<T>(options: FramePublisherOptions<T>): FramePublisher<T> {
  type Ticket = { generation: number; handle: number | null; value: T };
  let active = true;
  let generation = 0;
  let pending: Ticket | null = null;

  const cancel = () => {
    const previous = pending;
    pending = null;
    generation++;
    // Clear ownership before calling the scheduler: even a copied/reentrant
    // callback must see an invalid ticket, including handle zero.
    if (previous && previous.handle !== null) options.cancel(previous.handle);
  };

  return {
    schedule(value) {
      if (!active) return;
      if (pending) {
        pending.value = value;
        return;
      }
      const ticket: Ticket = { generation: ++generation, handle: null, value };
      pending = ticket;
      try {
        const handle = options.request(() => {
          if (!active || pending !== ticket || generation !== ticket.generation) return;
          // A thrown publisher or a reentrant schedule must not strand the
          // current frame or overwrite a newer request's ownership.
          pending = null;
          options.publish(ticket.value);
        });
        if (pending === ticket) ticket.handle = handle;
        else options.cancel(handle);
      } catch (error) {
        if (pending === ticket) {
          pending = null;
          generation++;
        }
        throw error;
      }
    },
    immediate(value) {
      cancel();
      if (active) options.publish(value);
    },
    cancel,
    activate() {
      active = true;
    },
    dispose() {
      active = false;
      cancel();
    },
  };
}

