import { describe, expect, it, vi } from "vitest";
import { createFramePublisher, type FramePublisher } from "../frame-publisher";

function fixture<T>() {
  let nextHandle = 0;
  const callbacks = new Map<number, () => void>();
  const cancelled: number[] = [];
  const published: T[] = [];
  const request = vi.fn((callback: () => void) => {
    const handle = nextHandle++;
    callbacks.set(handle, callback);
    return handle;
  });
  // Retain callbacks deliberately: cancellation cannot retract a callback
  // already copied by an event loop or a previous component lifecycle.
  const cancel = vi.fn((handle: number) => { cancelled.push(handle); });
  const publish = vi.fn((value: T) => { published.push(value); });
  const publisher = createFramePublisher<T>({ request, cancel, publish });
  return { publisher, callbacks, cancelled, published, request, cancel, publish,
    fire: (handle: number) => callbacks.get(handle)!() };
}

describe("frame-batched presentation ownership", () => {
  it("starts active before effects and publishes only the latest scheduled value once", () => {
    const f = fixture<number>();
    f.publisher.schedule(1);
    f.publisher.schedule(2);
    f.publisher.schedule(3);
    expect(f.request).toHaveBeenCalledTimes(1);
    expect(f.published).toEqual([]);
    f.fire(0);
    expect(f.published).toEqual([3]);
    f.fire(0);
    expect(f.published).toEqual([3]);
  });

  it("preserves legitimate null and undefined values instead of treating them as an empty queue", () => {
    const f = fixture<string | null | undefined>();
    f.publisher.schedule(null);
    f.fire(0);
    f.publisher.schedule(undefined);
    f.fire(1);
    expect(f.published).toEqual([null, undefined]);
  });

  it("cancels handle zero and prevents a copied old callback from consuming a newer request", () => {
    const f = fixture<string>();
    f.publisher.schedule("old");
    f.publisher.cancel();
    expect(f.cancelled).toEqual([0]);
    f.publisher.schedule("new");
    f.fire(0);
    expect(f.published).toEqual([]);
    f.fire(1);
    expect(f.published).toEqual(["new"]);
  });

  it("publishes urgent termination immediately and invalidates every older frame", () => {
    const f = fixture<{ status: string; sequence: number }>();
    f.publisher.schedule({ status: "running", sequence: 1 });
    f.publisher.schedule({ status: "running", sequence: 2 });
    f.publisher.immediate({ status: "finished", sequence: 3 });
    expect(f.published).toEqual([{ status: "finished", sequence: 3 }]);
    f.fire(0);
    expect(f.published).toEqual([{ status: "finished", sequence: 3 }]);
  });

  it("keeps scheduling available after an urgent pause and resume", () => {
    const f = fixture<string>();
    f.publisher.schedule("old-running");
    f.publisher.immediate("paused");
    f.publisher.immediate("running");
    f.publisher.schedule("latest-running");
    f.fire(0);
    f.fire(1);
    expect(f.published).toEqual(["paused", "running", "latest-running"]);
  });

  it("disposes pending work and ignores both queued and urgent values until reactivated", () => {
    const f = fixture<number>();
    f.publisher.schedule(1);
    f.publisher.dispose();
    f.publisher.schedule(2);
    f.publisher.immediate(3);
    f.fire(0);
    expect(f.published).toEqual([]);
    expect(f.request).toHaveBeenCalledTimes(1);
  });

  it("survives Strict Mode disposal and activation without reviving earlier lifecycle callbacks", () => {
    const f = fixture<string>();
    f.publisher.schedule("first-mount");
    f.publisher.dispose();
    f.publisher.activate();
    f.publisher.schedule("second-mount");
    f.fire(0);
    expect(f.published).toEqual([]);
    f.fire(1);
    expect(f.published).toEqual(["second-mount"]);
  });

  it("does not discard a valid pre-effect frame when an already active publisher activates", () => {
    const f = fixture<string>();
    f.publisher.schedule("before-effect");
    f.publisher.activate();
    f.fire(0);
    expect(f.published).toEqual(["before-effect"]);
    expect(f.cancelled).toEqual([]);
  });

  it("clears frame ownership before a throwing publisher so a later frame can proceed", () => {
    const f = fixture<number>();
    f.publish.mockImplementationOnce(() => { throw new Error("paint-failed"); });
    f.publisher.schedule(1);
    expect(() => f.fire(0)).toThrow("paint-failed");
    f.publisher.schedule(2);
    f.fire(0);
    f.fire(1);
    expect(f.published).toEqual([2]);
  });

  it("leaves no queued old value behind when an immediate publisher throws", () => {
    const f = fixture<number>();
    f.publisher.schedule(1);
    f.publish.mockImplementationOnce(() => { throw new Error("urgent-failed"); });
    expect(() => f.publisher.immediate(2)).toThrow("urgent-failed");
    f.fire(0);
    f.publisher.schedule(3);
    f.fire(1);
    expect(f.published).toEqual([3]);
  });

  it("allows a publisher to schedule the next frame without the old callback overwriting it", () => {
    const f = fixture<number>();
    f.publish.mockImplementation(value => {
      f.published.push(value);
      if (value === 1) f.publisher.schedule(2);
    });
    f.publisher.schedule(1);
    f.fire(0);
    f.fire(0);
    f.fire(1);
    expect(f.published).toEqual([1, 2]);
  });

  it("clears a request that throws before returning its frame handle", () => {
    const f = fixture<number>();
    f.request.mockImplementationOnce(() => { throw new Error("request-failed"); });
    expect(() => f.publisher.schedule(1)).toThrow("request-failed");
    f.publisher.schedule(2);
    f.fire(0);
    expect(f.published).toEqual([2]);
  });

  it("invalidates a cancelled callback before invoking a reentrant scheduler cancellation", () => {
    const f = fixture<number>();
    f.cancel.mockImplementation(handle => { f.fire(handle); });
    f.publisher.schedule(1);
    f.publisher.immediate(2);
    expect(f.published).toEqual([2]);
  });

  it("handles a scheduler that invokes a frame synchronously without stranding the next request", () => {
    const published: number[] = [];
    const cancel = vi.fn();
    const publisher: FramePublisher<number> = createFramePublisher({
      request: callback => { callback(); return 0; }, cancel,
      publish: value => { published.push(value); },
    });
    publisher.schedule(1);
    publisher.schedule(2);
    expect(published).toEqual([1, 2]);
    expect(cancel).toHaveBeenCalledTimes(2);
  });
});
